// Group historical subjects by their date without moving or changing existing notes.
const HISTORY_YEAR_PREFIX='@history-year:',HISTORY_YEAR_MARKER='@year:';
function historyYearParts(label,sortYear=null){
 const text=String(label||'').trim(),m=text.match(/^(기원전|기원(?:후)?)\s*(\d+)(년|세기)(?:\s*~\s*(?:기원전|기원(?:후)?)\s*\d+년)?(경)?/);
 if(m){const bc=m[1]==='기원전',number=Number(m[2]),century=m[3]==='세기',approx=!!m[4],year=century?(bc?-number*100:(number-1)*100+1):(bc?-number:number);if(!number||!Number.isFinite(year))return null;return {id:(bc?'bc-':'ad-')+(century?'century-':'')+number+(approx?'-approx':''),year,label:(bc?'BC ':'AD ')+number+(century?'세기':'')+(approx?'경':'')}}
 if(Number.isInteger(sortYear)&&sortYear!==0){const bc=sortYear<0,number=Math.abs(sortYear);return {id:(bc?'bc-':'ad-')+number,year:sortYear,label:(bc?'BC ':'AD ')+number}}
 return null;
}
function historyYearEra(year){if(year< -1513)return 0;if(year<= -1473)return 1;if(year< -607)return 2;if(year< -2)return 3;if(year<=70)return 4;return 5}
function historyYearFromId(id){const m=String(id).match(/^(bc|ad)-(century-)?(\d+)(-approx)?$/);if(!m)return null;const number=Number(m[3]),bc=m[1]==='bc',century=!!m[2],year=century?(bc?-number*100:(number-1)*100+1):(bc?-number:number);return number&&Math.abs(year)<=9999?{id,year,label:(bc?'BC ':'AD ')+number+(century?'세기':'')+(m[4]?'경':'')}:null}
function historyYearGroups(){
 const map=new Map(),unknown=[],baseNames=new Set(studyHistory.flatMap(([,items])=>items.map(x=>x[0])));let unknownCustom=false;
 function add(name,kind,date,sort){if(!subjectVisible('history',name))return;const parts=historyYearParts(date,sort),key=personalSubjectKey(name,kind);if(!parts){unknown.push(key);return}let group=map.get(parts.id);if(!group){group={...parts,key:HISTORY_YEAR_PREFIX+parts.id,members:[],era:historyYearEra(parts.year)};map.set(parts.id,group)}if(!group.members.includes(key))group.members.push(key)}
 for(const [,items] of studyHistory)for(const [name,kind] of items){const item=subjectOverride('history',name);add(name,kind,personalHistoryTime(name),item?.sort_year)}
 for(const item of customSubjects('history'))if(!baseNames.has(item.name)&&!item.name.startsWith(HISTORY_YEAR_MARKER)){if(subjectVisible('history',item.name)&&!historyYearParts(item.time_label,item.sort_year))unknownCustom=true;add(item.name,'history',item.time_label,item.sort_year)}
 for(const item of personalCatalog.filter(x=>x.field==='history'&&x.name.startsWith(HISTORY_YEAR_MARKER))){const id=item.name.slice(HISTORY_YEAR_MARKER.length),base=historyYearFromId(id);if(!base)continue;let group=map.get(id);if(!group){group={...base,key:HISTORY_YEAR_PREFIX+id,members:[],era:historyYearEra(base.year)};map.set(id,group)}group.hidden=!!item.hidden;const override=historyYearParts(item.time_label,item.sort_year);if(override){group.label=override.label;group.year=override.year;group.era=historyYearEra(override.year)}}
 let result=[...map.values()].filter(g=>!g.hidden).sort((a,b)=>a.year-b.year||a.label.localeCompare(b.label,'ko'));
 const unknownKey=HISTORY_YEAR_PREFIX+'unknown';if(unknownCustom||notes.some(n=>!familyInternal(n)&&(n.person===unknownKey||noteHasSubject(n.id,unknownKey)||unknown.some(k=>n.person===k||noteHasSubject(n.id,k)))))result.push({id:'unknown',key:unknownKey,label:'시기 미상',year:null,members:unknown,era:6});
 return result;
}
function historyYearGroup(key){return historyYearGroups().find(g=>g.key===key)}
function historyYearLabel(key){return historyYearGroup(key)?.label||historyYearFromId(String(key).slice(HISTORY_YEAR_PREFIX.length))?.label||'시기 미상'}
function historyYearNotes(group){if(!group)return [];const keys=new Set([group.key,...group.members]);return notes.filter(n=>!familyInternal(n)&&(keys.has(n.person)||[...keys].some(k=>noteHasSubject(n.id,k))))}
function historyYearRow(group,gap=0){const ns=historyYearNotes(group);return `<div class="person-row ${ns.length?'has-notes':'no-notes'}${noteSidesClass(ns)}${gap?' history-gap':''}" ${gap?`style="--history-gap:${gap}px"`:''}><div class="side">${sideNotes(ns.filter(n=>n.author==='mine'),'mine',group.key)}</div><a class="person personal-subject" href="${idHash(group.key)}?from=history">${esc(group.label)}</a><div class="side">${sideNotes(ns.filter(n=>n.author==='bora'),'bora',group.key)}</div></div>`}
function renderHistoryYears(q){
 const groups=historyYearGroups().filter(g=>!q||g.label.toLocaleLowerCase().includes(q)),bands=[[],[],[],[],[],[],[]];let previous=null;
 for(const g of groups){const difference=g.year!==null&&previous!==null?Math.max(0,g.year-previous):0,gap=difference>=2000?90:difference>=1000?72:difference>=500?50:difference>=300?36:difference>=100?22:difference>=50?10:0;previous=g.year;bands[g.era].push(historyYearRow(g,gap))}
 return bands.map((rows,i)=>rows.length?`<section class="era-band era-band-${i}" aria-label="${i===6?'시기 미상':'역사 연도'}">${rows.join('')}</section>`:'').join('');
}
function openHistoryYearEditor(key=null){
 const group=key?historyYearGroup(key):null;if(key&&(!group||group.id==='unknown'))return;const d=document.createElement('dialog');d.className='personal-edit-dialog';d.innerHTML=`<form class="personal-edit-form"><div class="personal-edit-head"><h2>${key?'연도 수정':'연도 추가'}</h2><button type="button" data-close aria-label="닫기">×</button></div><label>시기<select name="epoch"><option value="bc">기원전</option><option value="ad">기원후</option></select></label><label>연도<input type="number" name="year" inputmode="numeric" min="1" max="9999" step="1" required placeholder="연도"></label><p class="personal-edit-error" role="status"></p><button type="submit" class="primary">${key?'저장':'추가'}</button></form>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});const f=d.querySelector('form');if(group){f.elements.epoch.value=group.year<0?'bc':'ad';f.elements.year.value=String(Math.abs(group.year))}d.showModal();enhanceHistoryYearDialog(d,group);if(group)addSubjectDelete(d,()=>removeHistoryYear(key));
 f.onsubmit=async e=>{e.preventDefault();const n=Number(f.elements.year.value),error=d.querySelector('.personal-edit-error'),save=f.querySelector('[type=submit]');if(!Number.isInteger(n)||n<1||n>9999){error.textContent='연도를 확인해 주세요.';return}if(!f.elements.epoch.value){error.textContent='BC 또는 AD를 선택해 주세요.';return}const bc=f.elements.epoch.value==='bc',id=(bc?'bc-':'ad-')+n,year=bc?-n:n,existing=historyYearGroups().find(x=>x.id!==group?.id&&x.year===year&&!x.id.includes('century')&&!x.id.endsWith('approx'));if(existing){error.textContent='이미 있는 연도예요.';return}if(!key&&historyYearGroups().some(x=>x.id===id)){error.textContent='이미 있는 항목이에요.';return}const marker=HISTORY_YEAR_MARKER+(group?.id||id),data={field:'history',name:marker,era:studyHistory[historyYearEra(year)]?.[0]||'그 이후',time_label:(bc?'기원전 ':'기원 ')+n+'년',sort_year:year};save.disabled=true;save.setAttribute('aria-busy','true');try{const result=await personalWithPin(pin=>rpc('study_subject_catalog_change',{p_password:pin,p_action:'save',p_data:data}));if(!result)return;personalCatalog=await getAll('study_subject_catalog');d.close();if(key)personView(key);else location.hash=idHash(HISTORY_YEAR_PREFIX+id)+'?from=history'}catch(err){showPersonalError(error,err)}finally{save.disabled=false;save.removeAttribute('aria-busy')}};
}
async function removeHistoryYear(key){const group=historyYearGroup(key);if(!group||group.id==='unknown')return;if(!confirm('이 연도를 목록에서 지울까요?'))return;try{const r=await personalWithPin(pin=>rpc('study_subject_catalog_change',{p_password:pin,p_action:'hide',p_data:{field:'history',name:HISTORY_YEAR_MARKER+group.id}}));if(!r)return;personalCatalog=await getAll('study_subject_catalog');location.hash='#/people?field=history';return true}catch(err){alert(err.message||'삭제하지 못했어요. 다시 시도해 주세요.');return false}}
